const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const atlanta = ee.Geometry.Point([-84.3880, 33.7490]).buffer(20000); // 20km buffer for urban area

  // Time periods
  const july2013 = ee.DateRange('2013-07-01', '2013-07-31');
  const dec2013 = ee.DateRange('2013-12-01', '2013-12-31');

  // 2. Data Acquisition - VIIRS Nighttime Lights
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  const julyCollection = viirs
    .filterBounds(atlanta)
    .filterDate(july2013);

  const decCollection = viirs
    .filterBounds(atlanta)
    .filterDate(dec2013);

  // Check data availability
  const julyCount = julyCollection.size().getInfo();
  const decCount = decCollection.size().getInfo();

  print(`July 2013 Images: ${julyCount}, December 2013 Images: ${decCount}`);

  if (julyCount === 0 || decCount === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const julyImg = julyCollection.median();
  const decImg = decCollection.median();

  // 3. Processing - Check valid pixels
  const julyCountPixels = julyImg
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: atlanta,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  const decCountPixels = decImg
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: atlanta,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  print(`July valid pixels: ${julyCountPixels}, December valid pixels: ${decCountPixels}`);

  if (julyCountPixels === 0 || decCountPixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean radiance
  const julyMean = julyImg
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: atlanta,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  const decMean = decImg
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: atlanta,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  print(`July mean radiance: ${julyMean.toFixed(4)}`);
  print(`December mean radiance: ${decMean.toFixed(4)}`);
  print(`Difference (Dec-Jul): ${(decMean - julyMean).toFixed(4)}`);

  // 5. Validation & Final Answer
  if (julyMean === null || decMean === null || 
      isNaN(julyMean) || isNaN(decMean) ||
      julyMean < 0 || decMean < 0) { // VIIRS values should be non-negative
    print("<answer>C3</answer>");
  } else if (decMean > julyMean) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
